def as_record(self):
    root = Path(__file__).resolve().parents[2]
    paths = ('legacy_annotation/homology_result_acquisition/configuration.py', 'legacy_annotation/homology_result_acquisition/credit.py', 'legacy_annotation/homology_result_acquisition/from_parent.py', 'legacy_annotation/homology_result_acquisition/goal.py', 'legacy_annotation/homology_result_acquisition/homology_operations.py', 'legacy_annotation/homology_result_acquisition/to_parent.py', 'legacy_annotation/homology_result_acquisition/episode.py', 'legacy_annotation/homology_result_acquisition/binding_identity.py', 'legacy_annotation/homology_result_acquisition/task.py', 'legacy_annotation/homology_result_acquisition/task_state.py', 'legacy_annotation/homology_result_acquisition/task_protocol.py', 'legacy_annotation/homology_result_acquisition/task_decision.py', 'legacy_annotation/homology_result_acquisition/task_instructions.py', 'legacy_annotation/homology_result_acquisition/task_actions.py', 'legacy_annotation/homology_result_acquisition/task_report.py', 'library/homology_episode_contracts.py', 'library/homology_custody.py', 'library/homology_custody_configuration.py', 'library/homology_received_records.py', 'library/homology_native_events.py', 'library/homology_episode_family.py', 'library/monitoring_credit.py', 'legacy_annotation/homology_result_acquisition/internal_summary.py', 'legacy_annotation/homology_result_acquisition/yield_estimator.py', 'legacy_annotation/homology_result_acquisition/waiting.py', '../../execution_contracts.py', 'execution_recording.py', 'native_measurement.py', 'native_events.py')
