    return {'version': 'root_legacy_private_homology_v1', 'commissioning_parent': 'improvement', 'binding_path': 'legacy_annotation/homology_result_acquisition', 'binding_id': 'job_results', 'implementation_sha256': hashlib.sha256(canonical(hashes).encode()).hexdigest(), 'registry_directory': str(self.jobs.directory), 'registry_configuration': self.jobs.config, 'parser_policy': self.parser_policy.to_dict(), 'credit_binding': self.binding_for('job_results'), 'credit_calculator': _binding(self.monitoring_projector if 'job_results' == 'job_monitor' else self._job_credit_calculator), 'statistics': None if self.statistics is None else self.statistics.as_record()}
